def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    my_c = me.count('C')

    # Last opponent action and streak
    last = op[-1]
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last:
            run += 1
        else:
            break

    # Mutual cooperation streak
    cc_run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C' and me[i] == 'C':
            cc_run += 1
        else:
            break

    # --- Absolute opponent detectors ---
    if op_d == 0:
        # Always cooperates: exploit near end, otherwise keep mutual C to farm 3s.
        if n >= 94:
            return 'D'
        return 'C'

    if op_c == 0:
        return 'D'

    # --- Almost always defect ---
    if op_c <= max(1, n // 20) and n >= 8:
        return 'D'

    # --- Almost always cooperate ---
    if op_d <= max(1, n // 12) and n >= 8:
        # Farm mutual cooperation, but grab the final rounds.
        if n >= 96:
            return 'D'
        return 'C'

    # --- Late game exploitation ---
    if n >= 96:
        # Against mostly-cooperative opponents, defect hard at the end.
        if op_c * 3 >= n * 2:
            return 'D'
        if last == 'C':
            return 'D'
        return 'D' if op_d * 2 < n else 'D'

    # --- Tit-for-tat base with forgiveness ---
    if last == 'D':
        # Multiple consecutive defections: retaliate strongly.
        if run >= 3:
            return 'D'
        if run == 2:
            # If opponent is fundamentally cooperative, forgive once.
            if op_c * 3 >= n * 2 and last == 'D':
                # Test forgiveness: if we already retaliated, go back to C.
                if me[-1] == 'D':
                    return 'C'
                return 'D'
            return 'D'
        # Single defection: retaliate once, then return to cooperation.
        if n >= 2 and me[-1] == 'D' and op[-2] == 'C':
            # We already punished; go back to C to restore cooperation.
            return 'C'
        # Against mostly-defecting opponent, keep defecting.
        if op_d * 2 > n:
            return 'D'
        return 'D'

    # Opponent just cooperated.
    # If we defected last round and they responded with C, they're forgiving:
    # cooperate to keep the profitable mutual-C cycle going.
    if me[-1] == 'D':
        return 'C'

    # Opponent mostly defects but just cooperated: reward with C only if
    # their defection rate isn't too high.
    if op_d * 2 > n:
        return 'D'

    # --- Exploitation probing against highly cooperative opponents ---
    # If opponent has been very cooperative and we have a long CC streak,
    # occasionally defect to steal a 5, but not so often it collapses cooperation.
    if op_c * 5 >= n * 4 and n >= 10:
        # Deterministic probes spaced out, avoiding the final few rounds.
        if n < 90 and n % 11 == 0 and cc_run >= 3:
            return 'D'
        return 'C'

    # For mixed opponents, cooperate to build trust; retaliate on D handled above.
    return 'C'
